<?php
 namespace ehr; require_once(__DIR__ . '/../../../../init.php'); require_once(__DIR__ . '/../autoload.php'); interface iResourceItem { const EHR_STATE_CHANGE = 0, EHR_STATE_DELETE = 1; const ITEM_SOURCE_SICKLIST_RELATEDPERSON = 0, ITEM_SOURCE_SICKLIST_CONDITION = 1, ITEM_SOURCE_SICKLIST_EPISODEOFCARE = 2, ITEM_SOURCE_SICKLIST_CLAIM = 3, ITEM_SOURCE_SICKLIST_ENCOUNTER = 4, ITEM_SOURCE_SICKLIST_ENCOUNTER2 = 5, ITEM_SOURCE_SICKLIST_COMPOSITION = 6, ITEM_SOURCE_SICKLIST_ENCOUNTER3 = 7, ITEM_SOURCE_SICKLIST_RESERVE0 = 8, ITEM_SOURCE_SICKLIST_RESERVE1 = 9, ITEM_SOURCE_SICKLIST_RESERVE2 = 10, ITEM_SOURCE_SICKLIST_RESERVE3 = 11, ITEM_SOURCE_SICKLIST_RESERVE4 = 12, ITEM_SOURCE_SICKLIST_RESERVE5 = 13, ITEM_SOURCE_SICKLIST_RESERVE6 = 14, ITEM_SOURCE_SICKLIST_RESERVE7 = 15, ITEM_SOURCE_SICKLIST_RESERVE8 = 16, ITEM_SOURCE_SICKLIST_RESERVE9 = 17, ITEM_SOURCE_RECIPE_PATIENT = 18, ITEM_SOURCE_RECIPE_PRATITIONER = 19, ITEM_SOURCE_RECIPE_MEDICATIONPRESCRIPTION = 20, ITEM_SOURCE_RECIPE_MEDICATIONDISPENSE = 21, ITEM_SOURCE_RECIPE_CLAIM = 22; } class ResourceItem implements iResourceItem { protected $id; protected $state; protected $position; protected $guid; protected $versionGUID; protected $extraGuid; protected $json; protected $jsonName; protected $resource; public function __construct(Resource $aResource) { $this->resource = $aResource; $this->clearResourceItem(); } public function getResource(): ?Resource { return $this->resource; } public function getId(): int { return $this->id; } public function setId(int $id): void { $this->id = $id; } private function getJSONName(): ?string { return $this->jsonName; } public function getGUID(): ?string { return $this->guid; } public function setGUID(string $guid): void { $this->guid = $guid; } public function getVersionGUID(): ?string { return $this->versionGUID; } public function setVersionGUID(string $guid): void { $this->versionGUID = $guid; } public function clearGUIDs(): void { $this->guid = ''; $this->versionGUID = ''; } public function getState(): int { return $this->state; } public function setState(int $state): void { $this->state = $state; } public function getJSON(): \stdClass { return $this->json; } public function getJSONData(): string { return json_encode($this->json, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); } public function clearResourceItem(): void { $this->state = self::EHR_STATE_CHANGE; $this->id = 0; $this->position = 0; $this->guid = ''; $this->extraGuid = ''; $this->versionGUID = ''; $this->json = null; $this->jsonName = ''; unset($this->json); } public function __destruct() { unset($this->json); } public function initJSONbase(): void { $resource = $this->getResource(); $this->json = new \stdClass(); LinkJSON::addNodeEx($this->json, 'id', $this->getGUID()); $node = &LinkJSON::addNode($this->json, 'meta'); LinkJSON::addNodeEx($node, 'profile', [$this->getProfileSDvalue()]); if (!empty($resource->getFieldName()) && !empty($this->getId())) { LinkJSON::addIdentifierV($this->json, LinkSetup::ID_URL_MAP, "{$resource->getFieldName()}/{$this->getId()}"); } } public function getProfileSDvalue(): string { return LinkSetup::ID_URL_SD; } private function addReference(\stdClass &$node, string $linkName = ''): void { LinkJSON::addNode($node, 'reference', empty($linkName) ? $linkName : "{$this->getJSONName()}/{$this->getGUID()}"); } private function addSubReference(\stdClass &$node, string $name, string $linkName = ''): void { $new = LinkJSON::addNode($node, $name); $this->addReference($new, $linkName); } private function addContainedReference(&$node, string $guid): \stdClass { $new = &LinkJSON::addNode($node, 'contained'); $list = &LinkJSON::addNode($new, 'List'); LinkJSON::addNode($list, 'id', $guid); LinkJSON::addNode($list, 'status', 'current'); LinkJSON::addNode($list, 'mode', 'working'); $entry = &LinkJSON::addNode($list, 'entry'); $item = &LinkJSON::addNode($entry, 'item'); $this->addReference($item); return $new; } public function initData(array $record): void { } public function appendJSON(): void { } public static function formatNumber(float $number): string { $num = rtrim(sprintf('%.8F', $number), '0'); if ($num == 0 || ($num == (int) $num)) { $num .= '0'; } return $num; } public static function test() { header('Content-Type: application/json'); $j = new \stdClass(); LinkJSON::addNode($j, 'resourceType', 'Practitioner'); $node = &LinkJSON::addNode($j, 'meta'); LinkJSON::addNode($node, 'profile', array('http://fhir.org/fhir/StructureDefinition/by-practitioner')); $node = &LinkJSON::addNode($j, 'identifier'); $el = LinkJSON::addNodeElement($node); LinkJSON::addNode($el, 'system', 'http://uiip.bas-net.by/hl7/fhir/medical-information-system/00005'); LinkJSON::addNode($el, 'value', 'medDoctorCode/766'); $node = &LinkJSON::addNode($j, 'name'); LinkJSON::addNode($node, 'use', 'official'); LinkJSON::addNode($node, 'family', array('Донец')); LinkJSON::addNode($node, 'given', 'Марина'); LinkJSON::addNode($node, 'given', 'Александровна'); $node = &LinkJSON::addNode($j, 'practitionerRole'); $el = LinkJSON::addNodeElement($node); $node1 = &LinkJSON::addNode($el, 'managingOrganization'); LinkJSON::addNode($node1, 'reference', '"Organization/1'); $node2 = &LinkJSON::addNode($el, 'role'); $node3 = &LinkJSON::addNode($node2, 'coding'); $el = LinkJSON::addNodeElement($node3); LinkJSON::addNode($el, 'system', 'http://hl7.org/fhir/vs/practitioner-role'); LinkJSON::addNode($el, 'code', 'doctor'); echo json_encode($j, JSON_PRETTY_PRINT); } } 